<?php
declare(strict_types=1);
use ImAuthenticator\Security;use ImAuthenticator\Web;
$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireUser();$id=(int)($_GET['id']??$_POST['application_id']??0);$app=$db->one('SELECT * FROM applications WHERE id=? AND deleted_at IS NULL',[$id]);if(!$app){http_response_code(404);exit;}if(!$appAdmins->canManage((int)$user['id'],$id,'security')){http_response_code(403);exit('Brak uprawnień.');}$msg='';
if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);try{$action=(string)($_POST['action']??'save');if($action==='save'){$db->execute('INSERT INTO application_oauth_security(application_id,require_par,require_pkce,require_dpop,require_mtls,jar_required,jarm_enabled,token_exchange_enabled,updated_by) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE require_par=VALUES(require_par),require_pkce=VALUES(require_pkce),require_dpop=VALUES(require_dpop),require_mtls=VALUES(require_mtls),jar_required=VALUES(jar_required),jarm_enabled=VALUES(jarm_enabled),token_exchange_enabled=VALUES(token_exchange_enabled),updated_by=VALUES(updated_by)',[$id,isset($_POST['require_par'])?1:0,isset($_POST['require_pkce'])?1:0,isset($_POST['require_dpop'])?1:0,isset($_POST['require_mtls'])?1:0,isset($_POST['jar_required'])?1:0,isset($_POST['jarm_enabled'])?1:0,isset($_POST['token_exchange_enabled'])?1:0,(int)$user['id']]);$jwks=trim((string)($_POST['jwks_json']??''));if($jwks!==''){$decoded=json_decode($jwks,true,512,JSON_THROW_ON_ERROR);if(!is_array($decoded)||!isset($decoded['keys'])||!is_array($decoded['keys']))throw new RuntimeException('Nieprawidłowy JWKS.');$db->execute('INSERT INTO application_client_jwks(application_id,jwks_json) VALUES(?,?) ON DUPLICATE KEY UPDATE jwks_json=VALUES(jwks_json)',[$id,json_encode($decoded,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)]);}else$db->execute('DELETE FROM application_client_jwks WHERE application_id=?',[$id]);$audit->write('application.oauth_security.updated','success',(int)$user['id'],null,$id);$msg='<div class="alert success">Polityka OAuth zapisana.</div>';}elseif($action==='add_mtls'){$thumb=strtolower(preg_replace('/[^a-fA-F0-9]/','',(string)$_POST['thumbprint']));if(strlen($thumb)!==64)throw new RuntimeException('Thumbprint SHA-256 musi mieć 64 znaki hex.');$db->execute('INSERT INTO application_mtls_certificates(application_id,thumbprint_sha256,subject_dn,valid_until) VALUES(?,?,?,?)',[$id,$thumb,trim((string)$_POST['subject_dn'])?:null,trim((string)$_POST['valid_until'])?:null]);$msg='<div class="alert success">Certyfikat dodany.</div>';}elseif($action==='add_exchange'){$source=(int)$_POST['source_application_id'];$scopes=array_values(array_filter(preg_split('/\s+/',trim((string)$_POST['allowed_scopes']))?:[]));if($source<1||$source===$id||$scopes===[])throw new RuntimeException('Nieprawidłowa polityka Token Exchange.');$db->execute('INSERT INTO token_exchange_policies(source_application_id,target_application_id,allowed_scopes_json,enabled,created_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE allowed_scopes_json=VALUES(allowed_scopes_json),enabled=1',[$source,$id,json_encode($scopes,JSON_THROW_ON_ERROR),1,(int)$user['id']]);$msg='<div class="alert success">Polityka Token Exchange dodana.</div>';}}catch(Throwable $e){$msg='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}
$p=$oauthProofs->policy($app);$jwks=$db->one('SELECT jwks_json FROM application_client_jwks WHERE application_id=?',[$id]);$check=function(string $k)use($p):string{return !empty($p[$k])?' checked':'';};$certRows='';foreach($db->all('SELECT * FROM application_mtls_certificates WHERE application_id=? AND revoked_at IS NULL ORDER BY created_at DESC',[$id]) as $c)$certRows.='<tr><td><code>'.Web::e($c['thumbprint_sha256']).'</code></td><td>'.Web::e($c['subject_dn']?:'—').'</td><td>'.Web::e($c['valid_until']?:'—').'</td></tr>';$sourceOptions='';foreach($db->all('SELECT id,name FROM applications WHERE id<>? AND deleted_at IS NULL ORDER BY name',[$id]) as $a)$sourceOptions.='<option value="'.(int)$a['id'].'">'.Web::e($a['name']).'</option>';$exchange='';foreach($db->all('SELECT p.*,a.name FROM token_exchange_policies p JOIN applications a ON a.id=p.source_application_id WHERE p.target_application_id=? ORDER BY a.name',[$id]) as $x)$exchange.='<tr><td>'.Web::e($x['name']).'</td><td>'.Web::e($x['allowed_scopes_json']).'</td><td>'.((bool)$x['enabled']?'Aktywna':'Wyłączona').'</td></tr>';
$content='<div class="page-head"><div><h1>OAuth Security — '.Web::e($app['name']).'</h1><p>PAR, PKCE, DPoP, mTLS, JAR/JARM i Token Exchange.</p></div><a class="button" href="/admin/applications/'.$id.'">Aplikacja</a></div>'.$msg.'<form class="card" method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="application_id" value="'.$id.'"><label><input type="checkbox" name="require_par"'.$check('require_par').'> Wymagaj PAR</label><label><input type="checkbox" name="require_pkce"'.$check('require_pkce').'> Wymagaj PKCE S256 również dla confidential client</label><label><input type="checkbox" name="require_dpop"'.$check('require_dpop').'> Wymagaj DPoP</label><label><input type="checkbox" name="require_mtls"'.$check('require_mtls').'> Wymagaj mTLS</label><label><input type="checkbox" name="jar_required"'.$check('jar_required').'> Wymagaj JAR</label><label><input type="checkbox" name="jarm_enabled"'.$check('jarm_enabled').'> Włącz JARM</label><label><input type="checkbox" name="token_exchange_enabled"'.$check('token_exchange_enabled').'> Zezwól na Token Exchange do tego klienta</label><label>Client JWKS dla JAR<textarea name="jwks_json" rows="8">'.Web::e($jwks['jwks_json']??'').'</textarea></label><button class="primary" name="action" value="save">Zapisz politykę</button></form><section class="card"><h2>mTLS certificates</h2><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="application_id" value="'.$id.'"><label>SHA-256 thumbprint<input name="thumbprint" required></label><label>Subject DN<input name="subject_dn"></label><label>Ważny do<input type="datetime-local" name="valid_until"></label><button name="action" value="add_mtls">Dodaj certyfikat</button></form><div class="table-wrap"><table><thead><tr><th>Thumbprint</th><th>Subject</th><th>Ważny do</th></tr></thead><tbody>'.$certRows.'</tbody></table></div></section><section class="card"><h2>Token Exchange</h2><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="application_id" value="'.$id.'"><label>Źródłowa aplikacja<select name="source_application_id">'.$sourceOptions.'</select></label><label>Dozwolone scopes<input name="allowed_scopes" value="openid profile email"></label><button name="action" value="add_exchange">Dodaj politykę</button></form><div class="table-wrap"><table><thead><tr><th>Źródło</th><th>Scopes</th><th>Status</th></tr></thead><tbody>'.$exchange.'</tbody></table></div></section>';Web::page('OAuth Security',$content,$user);
